, "items": [{"name": "Salada da estação", "description": "Folhas, grãos, castanhas e molho de mel e mostarda.", "price": "R$ 34", "image": "https://images.unsplash.com/photo-1540189549336-e6e99c3679fe"}, {"name": "Pizza artesanal", "description": "Massa de fermentação natural, forno a lenha.", "price": "R$ 59", "image": "https://images.unsplash.com/photo-1565299624946-b28f40a0ae38"}, {"name": "Bowl do chef", "description": "Salmão, arroz, legumes frescos e gergelim.", "price": "R$ 48", "image": "https://images.unsplash.com/photo-1546069901-ba9599a7e63c"}, {"name": "Almoço executivo", "description": "Prato do dia com salada e sobremesa.", "price": "R$ 32", "image": "https://images.unsplash.com/photo-1504674900247-0877df9cc836"}]}}, {"id": "gallery", "type": "gallery", "enabled": true, "data": {"variant": "grid", "title": "O ambiente", "subtitle": "Venha nos visitar", "images": [{"src": "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4", "alt": "Salão principal"}, {"src": "https://images.unsplash.com/photo-1559339352-11d035aa65de", "alt": "Terraço"}, {"src": "https://images.unsplash.com/photo-1414235077428-338989a2e8c0", "alt": "Pratos autorais"}, {"src": "https://images.unsplash.com/photo-1504674900247-0877df9cc836", "alt": "Para compartilhar"}, {"src": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5", "alt": "Jantar"}, {"src": "https://images.unsplash.com/photo-1540189549336-e6e99c3679fe", "alt": "Opções leves"}]}}, {"id": "testimonials", "type": "testimonials", "enabled": true, "data": {"title": "O que dizem nossos clientes", "rating": "4,8 no Google", "items": [{"name": "Fernanda Rocha", "text": "Comida com gosto de casa de vó. O almoço executivo é farto e muito bem servido.", "role": "Google", "photo": "https://images.unsplash.com/photo-1494790108377-be9c29b29330"}, {"name": "Marcos Vieira", "text": "Fizemos a confraternização da empresa aqui e foi impecável do início ao fim.", "role": "Evento corporativo", "photo": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e"}, {"name": "Juliana Prado", "text": "A pizza de fermentação natural é a melhor da região. Voltamos toda semana.", "role": "iFood", "photo": "https://images.unsplash.com/photo-1438761681033-6461ffad8d80"}]}}, {"id": "faq", "type": "faq", "enabled": true, "data": {"title": "Perguntas frequentes", "items": [{"q": "Vocês fazem delivery?", "a": "Sim, pelo WhatsApp e pelos principais aplicativos."}, {"q": "Aceitam reservas?", "a": "Sim, reserve pelo WhatsApp com o número de pessoas e horário."}, {"q": "Têm opções vegetarianas?", "a": "Sim, temos pratos vegetarianos e sem glúten sinalizados no cardápio."}, {"q": "Fazem eventos?", "a": "Montamos cardápios para grupos a partir de 15 pessoas."}]}}, {"id": "cta", "type": "cta", "enabled": true, "data": {"eyebrow": "Mesas limitadas", "title": "Bateu a fome?", "text": "Reserve sua mesa ou peça no conforto de casa.", "image": "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4", "buttonText": "Pedir pelo WhatsApp", "buttonUrl": "whatsapp"}}, {"id": "contact", "type": "contact", "enabled": true, "data": {"title": "Contato", "text": "Estamos prontos para atender você.", "formTitle": "Envie sua mensagem"}}, {"id": "location", "type": "location", "enabled": true, "data": {"title": "Onde estamos", "text": ""}}]}'::jsonb
) on conflict (key) do update set
