o de você"}}}, {"id": "services", "type": "services", "enabled": true, "data": {"variant": "cards", "title": "Especialidades", "subtitle": "Cuidado completo em um só lugar", "items": [{"name": "Clínica geral", "description": "Consultas, check-ups e acompanhamento.", "price": "", "image": "https://images.unsplash.com/photo-1576091160399-112ba8d25d1d"}, {"name": "Odontologia", "description": "Prevenção, estética e implantes.", "price": "", "image": "https://images.unsplash.com/photo-1629909613654-28e377c37b09"}, {"name": "Exames", "description": "Coleta no local e laudos rápidos.", "price": "", "image": "https://images.unsplash.com/photo-1576091160550-2173dba999ef"}, {"name": "Check-up completo", "description": "Avaliação anual com vários especialistas.", "price": "", "image": "https://images.unsplash.com/photo-1538108149393-fbbd81895907"}]}}, {"id": "gallery", "type": "gallery", "enabled": true, "data": {"variant": "grid", "title": "Nossa estrutura", "subtitle": "", "images": [{"src": "https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d", "alt": "Recepção"}, {"src": "https://images.unsplash.com/photo-1629909613654-28e377c37b09", "alt": "Consultório odontológico"}, {"src": "https://images.unsplash.com/photo-1538108149393-fbbd81895907", "alt": "Sala de procedimentos"}, {"src": "https://images.unsplash.com/photo-1631217868264-e5b90bb7e133", "alt": "Atendimento humanizado"}]}}, {"id": "testimonials", "type": "testimonials", "enabled": true, "data": {"title": "O que dizem nossos clientes", "rating": "4,9 no Google", "items": [{"name": "Patrícia Gomes", "text": "Fui atendida no horário, com muita atenção. Explicaram tudo com calma.", "role": "Paciente", "photo": "https://images.unsplash.com/photo-1544005313-94ddf0286df2"}, {"name": "Roberto Nunes", "text": "Fiz meu check-up completo em uma manhã só. Organização excelente.", "role": "Google", "photo": "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e"}, {"name": "Aline Costa", "text": "Levo meus filhos desde pequenos. Equipe acolhedora e muito competente.", "role": "Paciente", "photo": "https://images.unsplash.com/photo-1494790108377-be9c29b29330"}]}}, {"id": "faq", "type": "faq", "enabled": true, "data": {"title": "Perguntas frequentes", "items": [{"q": "Atendem convênio?", "a": "Sim. Consulte a lista de convênios pelo WhatsApp."}, {"q": "Como agendar?", "a": "Pelo WhatsApp, telefone ou pessoalmente na recepção."}, {"q": "Tem consulta no mesmo dia?", "a": "Temos horários de encaixe diariamente para clínica geral."}]}}, {"id": "cta", "type": "cta", "enabled": true, "data": {"eyebrow": "", "title": "Agende sua consulta", "text": "Resposta rápida pelo WhatsApp em horário comercial.", "image": "", "buttonText": "Falar com a recepção", "buttonUrl": "whatsapp"}}, {"id": "contact", "type": "contact", "enabled": true, "data": {"title": "Contato", "text": "Nossa recepção responde rapidamente.", "formTitle": "Solicitar agendamento"}}, {"id": "location", "type": "location", "enabled": true, "data": {"title": "Onde estamos", "text": ""}}]}'::jsonb
